'use strict';

var factory = require( './factory.js' );
var base = require( './base.js' );
var canUseNative = require( './can_use_native.js' );
var addon = require( './../src/addon.node' );
var main;
/**
* Dispatches only eligible geometry to the actual addon.
* @private
* @returns {integer} INFO
*/
function dispatch() {
	if (canUseNative(arguments)) {
		return addon.apply(null, arguments);
	}
	return base.apply(null, arguments);
}
main = factory(dispatch);
module.exports = main;
